5: // Immutable objects plus an atomic, hash-bound pointer. Legacy Store/ledger stays untouched.
6: export class SessionStore {
7:   readonly root: string; private token = randomUUID(); private closed = false;
8:   constructor(root: string) {
9:     mkdirSync(resolve(root),{recursive:true}); this.root = realpathSync(root);
10:     const lock = join(this.root,'writer.lock');
11:     if (existsSync(lock)) {
12:       let owner: { pid: number; token: string };
13:       try { owner = JSON.parse(readFileSync(lock,'utf8')); if (!Number.isInteger(owner.pid) || !owner.token) throw new Error(); } catch { throw new WorkflowError('WRITE_CONFLICT','写锁损坏，保留原件并由操作者检查',409); }
14:       let alive = true; try { process.kill(owner.pid,0); } catch (e) { if ((e as NodeJS.ErrnoException).code === 'ESRCH') alive = false; }
15:       if (alive) throw new WorkflowError('WRITE_CONFLICT',`进程 ${owner.pid} 持有写租约`,409);
16:       renameSync(lock,join(this.root,`interrupted-lock-${owner.token}.json`));
17:     }
18:     try { writeFileSync(lock,JSON.stringify({pid:process.pid,token:this.token,createdAt:new Date().toISOString()}),{flag:'wx',mode:0o600}); } catch { throw new WorkflowError('WRITE_CONFLICT','写租约已被另一进程取得',409); }
19:     mkdirSync(join(this.root,'sessions'),{recursive:true});
20:   }
21:   private assertLease() {
22:     if (this.closed || JSON.parse(readFileSync(join(this.root,'writer.lock'),'utf8')).token !== this.token) throw new WorkflowError('WRITE_CONFLICT','当前实例不持有写租约',409);
23:   }
24:   private dir(id: string) { safeId.parse(id); return join(this.root,'sessions',id); }
25:   private atomic(path: string, value: unknown) {
26:     const temp = `${path}.${randomUUID()}.tmp`; const fd = openSync(temp,'wx',0o600);
27:     try { writeFileSync(fd,JSON.stringify(value,null,2)); fsyncSync(fd); } finally { closeSync(fd); }
28:     renameSync(temp,path); const dirFd = openSync(resolve(path,'..'),'r'); try { fsyncSync(dirFd); } finally { closeSync(dirFd); }
29:   }
30:   // Only observer selection is reused. Actual reads still validate the full
31:   // immutable object; metadata changes invalidate even an unchanged pointer.
32:   observationRevision(id: string): string {
33:     const dir=this.dir(id),pointer=join(dir,'current.json');if(!existsSync(pointer))return 'absent';
34:     try {
35:       const ref=JSON.parse(readFileSync(pointer,'utf8'));if(!/^[a-f0-9]{64}$/.test(ref.hash))throw new Error('pointer hash');
36:       const file=statSync(join(dir,`${ref.hash}.json`),{bigint:true});
37:       return `${ref.hash}:${file.dev}:${file.ino}:${file.size}:${file.mtimeNs}:${file.ctimeNs}`;
38:     } catch(e) { throw new WorkflowError('PERSISTENCE_FAILED',`状态损坏；保留原文件和不可变历史，请检查 ${dir}`,500,String(e)); }
39:   }
40:   load(id: string): Session|null {
41:     const dir = this.dir(id), pointer = join(dir,'current.json'); if (!existsSync(pointer)) return null;
42:     try {
43:       const ref = JSON.parse(readFileSync(pointer,'utf8')); if (!/^[a-f0-9]{64}$/.test(ref.hash)) throw new Error('pointer hash');
44:       const state = JSON.parse(readFileSync(join(dir,`${ref.hash}.json`),'utf8')) as Session;
45:       if (hash(state) !== ref.hash || state.schemaVersion !== schemaVersion || state.projectId !== id || !Number.isInteger(state.generation) || !Array.isArray(state.attempts) || !Array.isArray(state.views) || !Array.isArray(state.goals) || !Array.isArray(state.feedback)) throw new Error('schema or hash');
46:       return state;
47:     } catch (e) { throw new WorkflowError('PERSISTENCE_FAILED',`状态损坏；保留原文件和不可变历史，请检查 ${dir}`,500,String(e)); }
48:   }
49:   save(state: Session) {
50:     this.assertLease(); const dir = this.dir(state.projectId); mkdirSync(dir,{recursive:true});
51:     const sha = hash(state), target = join(dir,`${sha}.json`);
52:     if (!existsSync(target)) { const fd = openSync(target,'wx',0o600); try { writeFileSync(fd,JSON.stringify(state)); fsyncSync(fd); } finally { closeSync(fd); } }
53:     this.atomic(join(dir,'current.json'),{schemaVersion,hash:sha,generation:state.generation});
54:   }

