76:   if(type==='thread.started'){const thread=optionalString(x.thread_id);if(!thread)throw new WorkflowError('STREAM_SCHEMA','thread.started 缺 thread_id');return {...d,kind:'session',threadId:thread,action:'turn',label:'Codex 会话开始'};}
77:   if(type==='turn.started')return {...d,kind:'turn-start',turnId:optionalString(x.turn_id),action:'turn',status:'started',label:'开发轮次开始'};
78:   if(type==='turn.completed'||type==='turn.failed')return {...d,kind:type==='turn.completed'?'turn-complete':'turn-failed',turnId:optionalString(x.turn_id),action:'turn',status:type==='turn.completed'?'completed':'failed',label:type==='turn.completed'?'主代理本轮报告完成':'主代理本轮失败'};
