80:   if(!['item.started','item.updated','item.completed'].includes(type))throw new WorkflowError('STREAM_SCHEMA',`未支持的 Codex exec 事件类型 ${type}`);
81:   const item=object(x.item),itemType=item.type,itemId=optionalString(item.id);if(!itemId||typeof itemType!=='string')throw new WorkflowError('STREAM_SCHEMA','item 缺少 id 或 type');
82:   if(!['command_execution','file_change','agent_message','reasoning','mcp_tool_call','web_search','todo_list','error','collab_tool_call','collab_agent_tool_call','collabAgentToolCall','subAgentActivity'].includes(itemType))throw new WorkflowError('STREAM_SCHEMA',`未支持的 Codex item 类型 ${itemType}`);
83:   if(itemType==='reasoning'||itemType==='todo_list')return d;
84:   if(itemType==='agent_message')return type==='item.completed'?{...d,kind:'agent-report',action:'report',status:'reported',itemId,label:'主代理报告（未经产品验证）'}:d;
85:   if(itemType==='error')return {...d,kind:'error',action:'error',status:'failed',itemId,label:'工具错误'};
86:   if(itemType==='subAgentActivity'){
87:    const agentId=optionalString(item.agentThreadId),path=optionalString(item.agentPath),kind=item.kind;
88:    if(!agentId||!path||!['started','interacted','interrupted','completed'].includes(String(kind)))throw new WorkflowError('STREAM_SCHEMA','子代理活动身份或状态无效');
89:    return {...d,kind:'delegation',agentId,parentId:null,action:'delegate',status:kind==='completed'?'completed':kind==='interrupted'?'interrupted':kind==='started'?'started':'updated',itemId,label:'子代理活动'};
90:   }
91:   if(['collab_tool_call','collab_agent_tool_call','collabAgentToolCall'].includes(itemType)){
92:    // Current protocol carries sender/receiver thread IDs and each child's
93:    // agents_states. A completed tool call is not a completed child.
94:    const sender=optionalString(item.sender_thread_id)??optionalString(item.senderThreadId);
95:    const receivers=Array.isArray(item.receiver_thread_ids)?item.receiver_thread_ids:Array.isArray(item.receiverThreadIds)?item.receiverThreadIds:null;
96:    const states=item.agents_states??item.agentsStates;
97:    if(sender&&receivers){if(receivers.length>30||receivers.some(v=>!optionalString(v)))throw new WorkflowError('STREAM_SCHEMA','协作接收者身份无效');
98:     const mapped=states&&typeof states==='object'&&!Array.isArray(states)?states as Record<string,unknown>:{};
99:     return {...d,kind:'tool',action:'tool',status:itemStatus(item.status,type),itemId,label:'代理协作工具',children:receivers.map(v=>({agentId:v as string,senderId:sender,status:childStatus(mapped[v as string])}))};
100:    }
101:    const receiver=optionalString(item.receiver)??optionalString(item.recipient),fallbackSender=optionalString(item.sender)??'root';
102:    return {...d,kind:receiver?'delegation':'tool',agentId:receiver??'root',parentId:receiver?fallbackSender:null,action:receiver?'delegate':'tool',status:'unknown',itemId,label:receiver?'代理协作调用（子状态未知）':'协作工具（目标未报告）'};
103:   }
104:   const action=itemType==='file_change'?'edit':itemType==='command_execution'?'command':'tool';
105:   const changes=Array.isArray(item.changes)?item.changes:[];
106:   return {...d,kind:'tool',action,status:typeof item.exit_code==='number'&&item.exit_code!==0?'failed':itemStatus(item.status,type),itemId,label:itemType==='file_change'?'文件修改':itemType==='command_execution'?'命令执行':'工具调用',sourcePaths:itemType==='file_change'?sourcePaths(project,changes.map(c=>c&&typeof c==='object'?(c as Record<string,unknown>).path:null)):[]};
107:  }
108:  // Native rollout is an explicitly selected single transcript. The fields below
