8: export function normalizeCodex(raw:unknown):{kind:RoundEvent['kind'];description:RoundEvent['description'];threadId?:string;observeSource?:boolean} {
9:  const x=envelope.parse(raw);
10:  if(x.type==='thread.started'){if(!x.thread_id)throw new Error('thread id required');return {kind:'received',description:'stream-start',threadId:x.thread_id};}
11:  if(x.type==='turn.started')return {kind:'begin',description:'turn-start'};
12:  if(x.type==='turn.completed')return {kind:'completed',description:'turn-completed'};
13:  if(x.type==='turn.failed'||x.type==='error')return {kind:'failed',description:'turn-failed'};
14:  if(['item.started','item.updated','item.completed'].includes(x.type)){
15:   if(!x.item||!['command_execution','file_change','agent_message','reasoning','mcp_tool_call','web_search','todo_list','error','collab_tool_call','collab_agent_tool_call','collabAgentToolCall'].includes(x.item.type))throw new Error('unsupported item schema');
