41: function relativeSelection(value: string, source: string, mustExist: boolean): string {
42:   if (!value || isAbsolute(value) || value.includes('\\') || value.includes('\0') || value.split('/').includes('..'))
43:     throw new Error(`范围或排除路径须是来源根下的相对路径: ${value}`);
44:   const full = resolve(source, value);
45:   if (!contained(source, full)) throw new Error(`范围或排除路径越界: ${value}`);
46:   if (mustExist) safePath(source, value);
47:   else {
48:     let cursor = full;
49:     while (!existsSync(cursor)) cursor = dirname(cursor);
50:     if (!contained(source, realpathSync(cursor))) throw new Error(`排除路径经符号链接越界: ${value}`);
51:   }
52:   return relative(source, full) || '.';
53: }
