55: function destination(path: string): string {
56:   let cursor = resolve(path);
57:   const missing: string[] = [];
58:   while (!existsSync(cursor)) {
59:     missing.unshift(basename(cursor));
60:     const parent = dirname(cursor);
61:     if (parent === cursor) throw new Error(`数据目录无法解析: ${path}`);
62:     cursor = parent;
63:   }
64:   return resolve(realpathSync(cursor), ...missing);
65: }
