4: export function contained(root: string, path: string): boolean { const r = relative(root,path); return r === '' || (!r.startsWith('..' + '/') && r !== '..' && !isAbsolute(r)); }
5: export function safePath(root: string, path: string): string {
6:   if (isAbsolute(path) || path.split(/[\\/]/).includes('..') || path.includes('\0') || path.includes('\\')) throw new WorkflowError('SOURCE_PATH_REFUSED','来源路径越界');
7:   const base = realpathSync(root), dest = resolve(base,path);
8:   if (!contained(base,dest)) throw new WorkflowError('SOURCE_PATH_REFUSED','来源路径越界');
9:   let cursor = base;
10:   for (const part of relative(base,dest).split('/').filter(Boolean)) { cursor = join(cursor,part); if (lstatSync(cursor).isSymbolicLink()) throw new WorkflowError('SOURCE_SYMLINK_REFUSED','不读取符号链接'); }
11:   if (!contained(base,realpathSync(dest))) throw new WorkflowError('SOURCE_PATH_REFUSED','来源路径越界');
12:   return dest;
13: }
14: export function readSource(project: Project, path: string): string {
15:   if(project.exclude?.some(x=>contained(resolve(project.sourceRoot,x),resolve(project.sourceRoot,path))))throw new WorkflowError('SOURCE_SCOPE_REFUSED','文件在排除范围');
16:   const full = safePath(project.sourceRoot,path);
17:   if (!project.scope.some(scope => contained(resolve(realpathSync(project.sourceRoot),scope),full))) throw new WorkflowError('SOURCE_SCOPE_REFUSED','文件不在已登记范围');
18:   if (!lstatSync(full).isFile() || lstatSync(full).size > 5_000_000) throw new WorkflowError('SOURCE_LIMIT','文件不是可读小型源文件');
19:   return readFileSync(full,'utf8');
20: }
