21: export function mappingContinuity(s:Session,from:View|null|undefined,to:View|null|undefined,references:MappingReferences):'same-analysis'|'unchanged-mapping'|'needs-review' {
22:  if(!from||!to||from.source.hash!==to.source.hash||from.goal?.hash!==to.goal?.hash||!to.goal||from.source.partial||to.source.partial)return 'needs-review';
23:  if(from.attemptId===to.attemptId)return 'same-analysis';
24:  const basis=mappingBasis(from,references);if(!basis)return 'needs-review';
25:  let current=to;const visited=new Set<string>();
26:  while(current.attemptId!==from.attemptId){
27:   if(visited.has(current.attemptId)||mappingBasis(current,references)!==basis)return 'needs-review';visited.add(current.attemptId);
28:   const links=(s.analysisContinuations??[]).filter(x=>x.toAttemptId===current.attemptId&&x.sourceHash===to.source.hash&&x.goalHash===to.goal!.hash&&x.toAnalysisHash===hash(current.analysis));
29:   if(links.length!==1)return 'needs-review';
30:   const previous=s.views.filter(v=>v.attemptId===links[0].fromAttemptId&&v.source.hash===to.source.hash&&v.goal?.hash===to.goal!.hash&&hash(v.analysis)===links[0].fromAnalysisHash);
31:   if(previous.length!==1)return 'needs-review';current=previous[0];
32:  }
33:  return 'unchanged-mapping';
34: }
